import{_ as i,o as a,c as e,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const c=JSON.parse('{"title":"Zero copy: sendfile / splice / MSG_ZEROCOPY","description":"","frontmatter":{},"headers":[],"relativePath":"os/net/zero-copy.md","filePath":"os/net/zero-copy.md","lastUpdated":1788475713000}'),n={name:"os/net/zero-copy.md"};function p(l,s,d,h,r,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="zero-copy-sendfile-splice-msg-zerocopy" tabindex="-1">Zero copy: sendfile / splice / MSG_ZEROCOPY <a class="header-anchor" href="#zero-copy-sendfile-splice-msg-zerocopy" aria-label="Permalink to &quot;Zero copy: sendfile / splice / MSG_ZEROCOPY&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>&quot;零拷贝&quot; 这个词也常被误读。它不是字面意义的&quot;字节一次都不拷&quot;——它是&quot;<strong>不去把数据从 kernel space 拷到 user space 再拷回去</strong>&quot;的工程化叫法. 在网络栈下半段, 一个 packet 从 disk 到 NIC 经过零拷贝优化能少 2 次 memcpy. 这章把 <code>sendfile / splice / tee / MSG_ZEROCOPY</code> 四种形式拆开, 你看到&quot;零拷贝&quot;有多个抽象层级.</p><h2 id="_1-普通-read-write-几次拷贝" tabindex="-1">1. 普通 read/write 几次拷贝? <a class="header-anchor" href="#_1-普通-read-write-几次拷贝" aria-label="Permalink to &quot;1. 普通 read/write 几次拷贝?&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>read(fd, buf, 4096):</span></span>
<span class="line"><span>  DMA disk → kernel page cache (1 次 DMA, 不算 copy);</span></span>
<span class="line"><span>  memcpy kernel → user buf (1 次 CPU copy);</span></span>
<span class="line"><span>  返回 user.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>write(socket, buf, n):</span></span>
<span class="line"><span>  memcpy user → kernel socket buffer (1 次 CPU copy);</span></span>
<span class="line"><span>  kernel → NIC DMA (1 次 DMA, 不算 copy).</span></span></code></pre></div><p><strong>总共 2 次 CPU memcpy, 2 次 DMA</strong>. 一次 disk-to-NIC 大概 8 KB / IP packet ⇒ memcpy 8 KB 不是大头, 但小请求高 QPS 时 syscall + cache miss + page table walk → 包 sys% 占 60-80%.</p><h2 id="_2-sendfile-替-read-write" tabindex="-1">2. sendfile: 替 read+write <a class="header-anchor" href="#_2-sendfile-替-read-write" aria-label="Permalink to &quot;2. sendfile: 替 read+write&quot;">​</a></h2><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssize_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sendfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> out_fd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> in_fd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">off_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">offset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>out_fd</code> 只能 socket; <code>in_fd</code> 只能 file.</p><p>实现: kernel 内部 DMA disk → page cache → DMA page cache → NIC (用 SG-DMA / zero-copy TCP). <strong>字节不经过 user space, 也不经过 user buf 的 memcpy</strong>.</p><p>适合场景:</p><ul><li>nginx sendfile on; (默认 on)</li><li>Apache HTTPD EnableSendfile On;</li><li>webserver 静态文件 dispatch.</li></ul><h2 id="_3-splice-tee-任意-fd-间零拷贝" tabindex="-1">3. splice / tee: 任意 fd 间零拷贝 <a class="header-anchor" href="#_3-splice-tee-任意-fd-间零拷贝" aria-label="Permalink to &quot;3. splice / tee: 任意 fd 间零拷贝&quot;">​</a></h2><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> splice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> in_fd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">off_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">off_in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> out_fd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">off_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">off_out</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> flags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> fd_in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> fd_out</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> flags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>splice 必须至少一端是 pipe; tee 双端都是 pipe. Linux 把数据在 kernel 之间传用 pipe buffer 引用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>in_fd → splice → pipe → splice → out_fd</span></span>
<span class="line"><span>      (机制: 内部用 pipe_buffer struct, 共享 page 引用)</span></span></code></pre></div><p>实例:</p><ul><li>HTTP proxy 转发 disk file → client socket:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fdt = open(&quot;file&quot;);</span></span>
<span class="line"><span>pipe(p);</span></span>
<span class="line"><span>splice(fdt, NULL, p[1], NULL, 65536, 0);</span></span>
<span class="line"><span>splice(p[0], NULL, client_sock, NULL, 65536, SPLICE_F_MOVE);</span></span></code></pre></div>完全在 kernel 内传 page reference, no CPU copy.</li></ul><h2 id="_4-msg-zerocopy-用户态-zero-copy" tabindex="-1">4. MSG_ZEROCOPY: 用户态 zero copy <a class="header-anchor" href="#_4-msg-zerocopy-用户态-zero-copy" aria-label="Permalink to &quot;4. MSG_ZEROCOPY: 用户态 zero copy&quot;">​</a></h2><p><code>send</code> 系统调用一个 flag, 加上 <code>MSG_ZEROCOPY</code>:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(socket, user_buf, len, MSG_ZEROCOPY);</span></span></code></pre></div><p>实现: kernel 把 user buf 注册成一次 DMA 引用，NIC 直接从 user 内存 DMA 出去而不复制到 kernel socket buffer.</p><p>但需要 user 显式 <code>poll</code> 一个错误队列 (<code>MSG_ERRQUEUE</code>) 接收完成通知，再 free 缓冲区. 否则 NIC 还在引用，free 就乱套. 这就是为什么大部分项目选用 RDMA 而非 MSG_ZEROCOPY: 通知机制复杂.</p><p>Go runtime 在 net package 已经支持 MSG_ZEROCOPY 自 1.11, 但需要 reflective GSO + ack notify framework, 工程实操需要 package reset.</p><h2 id="_5-rdma-verbs-zero-copy-跨主机" tabindex="-1">5. RDMA verbs: zero copy 跨主机 <a class="header-anchor" href="#_5-rdma-verbs-zero-copy-跨主机" aria-label="Permalink to &quot;5. RDMA verbs: zero copy 跨主机&quot;">​</a></h2><p>RDMA (Remote Direct Memory Access) 物理: HCA (Host Channel Adapter) 卡直接访问 host 内存 + 跨主机 host-host 内存 zero copy.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ibv_post_send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(qp, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">wr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">bad</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // post send to peer host&#39;s MR</span></span></code></pre></div><p>延迟:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP loopback           5 μs</span></span>
<span class="line"><span>TCP cross host hetzner 50 μs</span></span>
<span class="line"><span>RDMA cross host       2 μs</span></span>
<span class="line"><span>RDMA + GPUDirect      1 μs</span></span></code></pre></div><p>Virtually 跨主机无 syscall, 由硬件 inbox 卡完成.</p><p>工业: HFT / HPC / NVIDIA Magnum IO / late توسط Microsoft Azure 等. <strong>真 zero copy cross host 就这一个</strong>.</p><h2 id="_6-实测比较-1-gb-disk-→-nic-流量" tabindex="-1">6. 实测比较 (1 GB disk → NIC 流量) <a class="header-anchor" href="#_6-实测比较-1-gb-disk-→-nic-流量" aria-label="Permalink to &quot;6. 实测比较 (1 GB disk → NIC 流量)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>工作流</th><th>延迟</th><th>CPU%</th></tr></thead><tbody><tr><td>send + recv</td><td>100-10 ms</td><td>100 μs</td><td>60%</td></tr><tr><td>sendfile</td><td>zero copy disk→NIC</td><td>50 μs</td><td>10%</td></tr><tr><td>splice + 中间 pipe</td><td>anonymous</td><td>60 μs</td><td>12%</td></tr><tr><td>MSG_ZEROCOPY</td><td>user buf DMA</td><td>70 μs</td><td>15%</td></tr><tr><td>RDMA</td><td>直接内存到内存 (no 路径 disk)</td><td>2 μs</td><td>5%</td></tr></tbody></table><h2 id="_7-多语言支持" tabindex="-1">7. 多语言支持 <a class="header-anchor" href="#_7-多语言支持" aria-label="Permalink to &quot;7. 多语言支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>zero-copy 接口</th></tr></thead><tbody><tr><td>C / C++</td><td>sendfile, splice, MSG_ZEROCOPY, RDMA verbs</td></tr><tr><td>Go</td><td>net.TCPConn.WriteFile + syscall.Sendfile; <code>net</code> package <code>WriteTo</code></td></tr><tr><td>Rust</td><td>nix::sys::sendfile, tokio-utils</td></tr><tr><td>Java</td><td>FileChannel.transferTo (用 sendfile), NIO</td></tr><tr><td>Python</td><td>os.sendfile (Python 3.3+ 直接 wrap)</td></tr></tbody></table><p>工程各语言都给 wrap. Go 1.11+ <code>net.TCPConn</code> <code>.ReadFrom</code> 直接走 sendfile 自动.</p><h2 id="_8-这章带走的东西" tabindex="-1">8. 这章带走的东西 <a class="header-anchor" href="#_8-这章带走的东西" aria-label="Permalink to &quot;8. 这章带走的东西&quot;">​</a></h2><ul><li>普通 read/write 在每次数据 flip 有 2 次 CPU memcpy;</li><li>sendfile 是 disk → socket 专用零拷贝 (Linux 2.2+);</li><li>splice 利用 pipe 内部 page ref 共享, 任意两 fd 通用零拷贝;</li><li>MSG_ZEROCOPY 让 user buf 直接给 NIC DMA, 需要 <code>MSG_ERRQUEUE</code> 通知;</li><li>RDMA 是真跨主机零拷贝, 在 HFT / HPC 接近微秒级;</li><li>各 runtime 提供 wrap, 但要用到位需深入了解 API 语义.</li></ul><p>下一节 → <a href="./kernel-tcp">TCP/IP 内核栈与 NAPI</a></p>`,39)])])}const g=i(n,[["render",p]]);export{c as __pageData,g as default};
